from fractions import Fraction as F
import random

# Claim: every standard-open set is K-open (K-topology is finer than standard).
# Proof: the K-topology has basis {(a,b)} ∪ {(a,b)\K}, K={1/n: n>=1}.
# Every open interval (a,b) is itself a K-basis element. A standard-open set is a
# union of open intervals, so it is a union of K-basis elements, hence K-open.
# The code below samples this argument (a sample, not a proof of the universal claim),
# then checks the strictness witness exactly.

random.seed(1)

def in_union(x, ivs):
    return any(a < x < b for a, b in ivs)

ok = True
for _ in range(300):
    # random standard-open set: finite union of open intervals with rational endpoints
    ivs = []
    for _ in range(random.randint(1, 4)):
        a = F(random.randint(-50, 50), random.randint(1, 10))
        b = a + F(random.randint(1, 50), random.randint(1, 10))
        ivs.append((a, b))
    for _ in range(30):
        x = F(random.randint(-600, 600), random.randint(1, 12))
        if in_union(x, ivs):
            # find the interval containing x; it is a K-basis element (type (a,b))
            a, b = next((a, b) for a, b in ivs if a < x < b)
            # K-basis element (a,b) contains x and is a subset of U by construction
            if not (a < x < b):
                ok = False
            # check subset on sample points of (a,b)
            for k in range(1, 20):
                y = a + (b - a) * F(k, 20)
                if not in_union(y, ivs):
                    ok = False

print("sampled: each point of standard-open U lies in a K-basis interval inside U:", ok)

# Strictness witness: V=(-1,1)\K is K-open but not standard-open (0 in V, no ball around 0 inside V)
def inV(x):
    if not (-1 < x < 1):
        return False
    return not (x > 0 and (1 / x).denominator == 1)

strict = True
for m in range(1, 200):
    delta = F(1, m)
    n = m + 1  # 1/n < delta
    pt = F(1, n)
    if not (abs(pt) < delta and not inV(pt)):
        strict = False
print("0 in V:", inV(F(0)), "; every sampled ball around 0 contains a point 1/n of K outside V:", strict)
print("Hence K-topology strictly finer; standard-open => K-open holds by the basis argument.")

if ok and strict and inV(F(0)):
    print("CHECK PASS: answer 'yes' is correct")
else:
    print("CHECK FAIL")
